const COCHIN_INFO={id:"cochin-kingdom",name:"Kingdom of Cochin (Perumpadappu Swaroopam)",motto:"Perumpadappu Swaroopam",capital:"Mahodayapuram / Cochin / Tripunithura",period:"1102 – 1949 CE",stateRegion:"Central Kerala (Kochi, Thrissur, Ernakulam)",dynasty:"Perumpadappu Swaroopam / Chera Lineage",portHub:"Kochi Port & Arabian Sea Spice Route",quickStats:[{label:"Founded Era",value:"1102 CE",icon:"👑"},{label:"Spice Hub",value:"Malabar Pepper",icon:"🌶️"},{label:"Maritime Port",value:"Kochi Harbor",icon:"⛵"},{label:"Great Reformer",value:"Sakthan Thampuran",icon:"⚔️"},{label:"Iconic Festival",value:"Thrissur Pooram",icon:"🐘"},{label:"Accession",value:"1949 to India",icon:"🇮🇳"}]},TIMELINE_DATA=[{year:"1102 CE",title:"Emersion of Perumpadappu Swaroopam",description:"Following the decline of Later Cheras of Mahodayapuram, the royal house of Cochin is established."},{year:"1341 CE",title:"Great Flood of Periyar & Origin of Kochi Port",description:"A massive flood silted the ancient port of Kodungallur and carved out the natural harbor of Kochi, turning it into a international trade hub."},{year:"1503 CE",title:"Fort Emmanuel & European Alliances",description:"King Unniraman Koyil I permits the Portuguese to build Fort Emmanuel at Fort Kochi, making it the first European fortress in India."},{year:"1555 CE",title:"Construction of Mattancherry Palace",description:"The Portuguese construct Mattancherry Palace (Dutch Palace) as a gift to Raja Veera Kerala Varma."},{year:"1790–1805 CE",title:"Reign of Sakthan Thampuran",description:"Raja Rama Varma IX (Sakthan Thampuran) modernizes revenue administration, breaks feudal landlord power, and inaugurates Thrissur Pooram."},{year:"1864–1888 CE",title:"Modernization & Port Development",description:"Raja Sir Rama Varma V pioneers modern healthcare, public works, and steam navigation across Cochin backwaters."},{year:"1949 CE",title:"Integration into Union of India",description:"Cochin Kingdom merges with Travancore to form Travancore-Cochin state, later part of modern Kerala."}],RULERS_DATA=[{name:"Unniraman Koyil I (1500–1503)",role:"Maritime Alliance Pioneer",achievements:" Welcomed Afonso de Albuquerque, established alliance against Calicut Zamorin, and transformed Kochi into India's premier international spice port."},{name:"Veera Kerala Varma (1537–1565)",role:"Palace & Cultural Patron",achievements:"Commissioned royal Ramayana mural paintings at Mattancherry Palace and strengthened international trade relations with Arab and European merchants."},{name:"Sakthan Thampuran / Rama Varma IX (1790–1805)",role:"The Strong Ruler of Cochin",achievements:"Ended feudal Naduvazhi corruption, developed Thrissur as cultural capital, built Vadakkunnathan Temple grounds, and founded Thrissur Pooram."},{name:"Sir Sri Rama Varma XV (1895–1914)",role:"Social & Administrative Modernizer",achievements:"Constructed the Ernakulam-Shoranur railway line out of personal royal funds, expanded schools, hospitals, and forest conservation."}],CONTRIBUTIONS_DATA={overview:"The Kingdom of Cochin was world-renowned as the 'Queen of the Arabian Sea', famous for its cosmopolitan trade, religious tolerance, and rich performing arts.",maritimeTrade:"Center of the global spice trade, exporting black pepper, cardamom, cinnamon, and ginger to Arabia, China, and Europe for over 8 centuries.",architecture:"Architectural monuments include Mattancherry Dutch Palace (with exquisite Kerala mural art), Fort Kochi, Hill Palace Tripunithura, and Paradesi Synagogue (1568).",culturalHarmony:"Fostered peaceful coexistence between Syrian Christians, Malabar Jews, Arab traders, Konkani Brahmins, and local Hindu traditions.",thrissurPooram:"Sakthan Thampuran established Thrissur Pooram in 1797 as an inclusive festival featuring caparisoned elephants, Kudamattam umbrella displays, and traditional Panchavadyam."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Mattancherry_Palace_Kochi.jpg/800px-Mattancherry_Palace_Kochi.jpg",caption:"Mattancherry Palace (Dutch Palace) — Royal venue of Cochin Kings with ancient Kerala murals",category:"Architecture"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Chinese_fishing_nets_Kochi_Kerala.jpg/800px-Chinese_fishing_nets_Kochi_Kerala.jpg",caption:"Chinese Fishing Nets at Fort Kochi — Legacy of maritime trade under Cochin Kingdom",category:"Maritime"}],REFERENCES=[{text:"Menon, A. Sreedhara (1962). Kerala District Gazetteers: Ernakulam. Government Press.",link:"#"},{text:"Menon, K. P. Padmanabha (1924). History of Kerala: Written in the Form of Notes on Visscher's Letters. Ernakulam.",link:"#"},{text:"Singh, Anantdeep (2010). Spice Routes and Maritime Trade in the Kingdom of Cochin.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={COCHIN_INFO:COCHIN_INFO,TIMELINE_DATA:TIMELINE_DATA,RULERS_DATA:RULERS_DATA,CONTRIBUTIONS_DATA:CONTRIBUTIONS_DATA,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});